CREATE FUNCTION dbo.MANDGHEMATCROSS (@GHEMAT INT,@DT1 BIGINT,@DT2 BIGINT) RETURNS TABLE AS RETURN ( SELECT     HES_M, SUM(CASE hes_t WHEN 99999999 THEN GHEMAT ELSE 0 END) AS DAST, SUM(CASE hes_t WHEN 99999998 THEN GHEMAT ELSE 0 END)   AS SARBAR, SUM(CASE WHEN hes_t < 99999998 THEN GHEMAT ELSE 0 END) AS MAVAD FROM         dbo.MANDGHEMAT(@GHEMAT, @DT1, @DT2) MANDGHEMAT GROUP BY HES_M )
